package com.secure.documentwallet;

import android.content.*;import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.fragment.app.FragmentActivity;

public class VaultSettingsActivity extends FragmentActivity {
 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.safeScreen(this);Ui.lightBars(this);if(!Session.valid()){finish();return;}LinearLayout page=VaultPageUi.page(this);LinearLayout head=VaultPageUi.header(this,"My Vault Settings","Security, appearance, devices, and tools");TextView lock=VaultPageUi.iconButton(this,"⌾","Lock Vault");lock.setOnClickListener(v->{SecureCache.clear(this);Session.lock();startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP));finish();});head.addView(lock,new LinearLayout.LayoutParams(Ui.dp(this,44),Ui.dp(this,44)));page.addView(head);page.addView(VaultPageUi.section(this,"Protection"));entry(page,"▣","Security And Backup","Encryption, recovery, and vault health",VaultHealthActivity.class);entry(page,"◇","Account And Devices","Backup account and PC portal",AccountDevicesActivity.class);entry(page,"◈","Appearance","Themes and motion",AppearanceActivity.class);page.addView(VaultPageUi.section(this,"Vault Tools"));entry(page,"◷","Expiry Centre","Renewals and important dates",ExpiryCentreActivity.class);entry(page,"↗","Secure Share Hub","Controlled document sharing",SecureShareHubActivity.class);entry(page,"✚","Emergency Access Kit","Selected essential information",EmergencyAccessActivity.class);entry(page,"≋","Vault Activity","Document and security history",VaultActivityTimelineActivity.class);entry(page,"↓","App Updates","OTA downloads and release information",AppUpdatesActivity.class);setContentView(VaultPageUi.scroll(this,page));}
 private void entry(LinearLayout page,String symbol,String title,String detail,Class<?> target){LinearLayout row=VaultPageUi.row(this,symbol,title,detail);row.setOnClickListener(v->startActivity(new Intent(this,target)));VaultPageUi.addRow(page,row);}
}
